import math

def is_power_of_two(n):
    if n <= 0:
        return False
    return (n & (n - 1)) == 0

solutions = []

for n in [2, 3, 4]:
    for x in range(n + 1, n + 6):
        # Calculate x^n + x - 2
        R = x**n + x - 2

        if is_power_of_two(R):
            # Find k such that 2^k = R
            k = int(math.log2(R))
            solutions.append((x, n, k))

print("Found solutions (x, n, k):", solutions)

# Check patterns in 2^k (i.e., R)
R_values = {
    (x, n): R for n in [2, 3, 4] for x in range(n + 1, n + 6) 
    if is_power_of_two(x**n + x - 2)
}

print("R values (2^k) corresponding to solutions:")
for (x, n), R in R_values.items():
    print(f"n={n}, x={x}: R = {R}")

